17	// Translator converts raw Elasticsearch aggregation results into Jaeger's metrics domain model
18	// (metrics.MetricFamily). It uses a configurable function to extract values from buckets,
19	// ensuring flexibility across different metric types (e.g., latencies, call rates).
20	type Translator struct {
21		bucketsToPointsFunc func(buckets []*elastic.AggregationBucketHistogramItem) []*Pair
22	}
23	
24	func NewTranslator(bucketsToPointsFunc func(buckets []*elastic.AggregationBucketHistogramItem) []*Pair) Translator {
25		return Translator{
26			bucketsToPointsFunc: bucketsToPointsFunc,
27		}
28	}
29	
30	// ToDomainMetricsFamily converts Elasticsearch aggregations to Jaeger's MetricFamily.
31	func (t *Translator) ToDomainMetricsFamily(m MetricsQueryParams, result *elastic.SearchResult) (*metrics.MetricFamily, error) {
32		domainMetrics, err := t.toDomainMetrics(m, result)
33		if err != nil {
34			return nil, fmt.Errorf("failed to convert aggregations to metrics: %w", err)
35		}
36	
37		if m.GroupByOperation {
38			m.metricName = strings.Replace(m.metricName, "service", "service_operation", 1)
39			m.metricDesc += " & operation"
40		}
41	
42		return &metrics.MetricFamily{
43			Name:    m.metricName,
44			Type:    metrics.MetricType_GAUGE,
45			Help:    m.metricDesc,
46			Metrics: domainMetrics,
47		}, nil
48	}
49	
50	// toDomainMetrics converts Elasticsearch aggregations to Jaeger metrics.
51	func (t *Translator) toDomainMetrics(m MetricsQueryParams, result *elastic.SearchResult) ([]*metrics.Metric, error) {
52		labels := buildServiceLabels(m.ServiceNames)
53	
54		if !m.GroupByOperation {
55			buckets, err := extractBuckets(result)
56			if err != nil {
57				return nil, err
58			}
59			return []*metrics.Metric{
60				{
61					Labels:       labels,
62					MetricPoints: toDomainMetricPoints(t.bucketsToPointsFunc(buckets)),
63				},
64			}, nil
65		}
66	
67		// Handle grouped results when groupByOp is true
68		agg, found := result.Aggregations.Terms(aggName)
69		if !found {
70			return nil, fmt.Errorf("%s aggregation not found", aggName)
71		}
72	
73		var metricsData []*metrics.Metric
74		for _, bucket := range agg.Buckets {
75			metric, err := t.processOperationBucket(bucket, labels)
76			if err != nil {
77				return nil, fmt.Errorf("failed to process bucket: %w", err)
78			}
79			metricsData = append(metricsData, metric)
80		}
81	
82		return metricsData, nil
83	}
84	
85	func buildServiceLabels(serviceNames []string) []*metrics.Label {
86		labels := make([]*metrics.Label, len(serviceNames))
87		for i, name := range serviceNames {
88			labels[i] = &metrics.Label{Name: "service_name", Value: name}
89		}
90		return labels
91	}
92	
93	func (t *Translator) processOperationBucket(bucket *elastic.AggregationBucketKeyItem, baseLabels []*metrics.Label) (*metrics.Metric, error) {
94		key, ok := bucket.Key.(string)
95		if !ok {
96			return nil, fmt.Errorf("bucket key is not a string: %v", bucket.Key)
97		}
98	
99		// Extract nested date_histogram buckets
100		dateHistAgg, found := bucket.Aggregations.DateHistogram(dateHistAggName)
101		if !found {
102			return nil, fmt.Errorf("date_histogram aggregation not found in bucket %q", key)
103		}
104	
105		// Combine base labels with operation label
106		labels := append(baseLabels, toDomainLabels(key)...)
107	
108		return &metrics.Metric{
109			Labels:       labels,
110			MetricPoints: toDomainMetricPoints(t.bucketsToPointsFunc(dateHistAgg.Buckets)),
111		}, nil
112	}
113	
114	// toDomainLabels converts the bucket key to Jaeger metric labels.
115	func toDomainLabels(key string) []*metrics.Label {
116		return []*metrics.Label{
117			{
118				Name:  "operation",
119				Value: key,
120			},
121		}
122	}
123	
124	// extractBuckets retrieves date histogram buckets from Elasticsearch results.
125	func extractBuckets(result *elastic.SearchResult) ([]*elastic.AggregationBucketHistogramItem, error) {
126		agg, found := result.Aggregations.DateHistogram(aggName)
127		if !found {
128			return nil, fmt.Errorf("%s aggregation not found", aggName)
129		}
130		return agg.Buckets, nil
131	}
132	
133	// toDomainMetricPoints converts Elasticsearch buckets to Jaeger metric points.
134	func toDomainMetricPoints(rawResult []*Pair) []*metrics.MetricPoint {
135		metricPoints := make([]*metrics.MetricPoint, 0, len(rawResult))
136		for _, pair := range rawResult {
137			mp := toDomainMetricPoint(pair)
138			if mp != nil {
139				metricPoints = append(metricPoints, mp)
140			}
141		}
142	
143		return metricPoints
144	}
145	
146	// toDomainMetricPoint converts a single Pair to a Jaeger metric point.
147	func toDomainMetricPoint(pair *Pair) *metrics.MetricPoint {
148		timestamp := toDomainTimestamp(pair.TimeStamp)
149		if timestamp == nil {
150			return nil
151		}
152	
153		return &metrics.MetricPoint{
154			Value:     toDomainMetricPointValue(pair.Value),
155			Timestamp: timestamp,
156		}
157	}
158	
159	// toDomainTimestamp converts milliseconds since epoch to protobuf Timestamp.
160	func toDomainTimestamp(millis int64) *types.Timestamp {
161		timestamp := time.Unix(0, millis*int64(time.Millisecond))
162		protoTimestamp, _ := types.TimestampProto(timestamp)
163		return protoTimestamp
164	}
165	
166	// toDomainMetricPointValue converts a float64 value to Jaeger's gauge metric point.
167	func toDomainMetricPointValue(value float64) *metrics.MetricPoint_GaugeValue {
168		return &metrics.MetricPoint_GaugeValue{
169			GaugeValue: &metrics.GaugeValue{
170				Value: &metrics.GaugeValue_DoubleValue{DoubleValue: value},
171			},
172		}
173	}
