34	func (d *Driver) Query(_ context.Context, query string, _ ...any) (driver.Rows, error) {
35		d.RecordedQueries = append(d.RecordedQueries, query)
36	
37		// Normalize whitespace so substring matching works regardless of indentation.
38		normalized := strings.Join(strings.Fields(query), " ")
39		for querySubstring, response := range d.QueryResponses {
40			normalizedSubstring := strings.Join(strings.Fields(querySubstring), " ")
41			if strings.Contains(normalized, normalizedSubstring) {
42				return response.Rows, response.Err
43			}
44		}
45	
46		return nil, nil
47	}
