50		_ context.Context,
51		query string,
52		_ ...driver.PrepareBatchOption,
53	) (driver.Batch, error) {
54		d.RecordedQueries = append(d.RecordedQueries, query)
55	
56		// Normalize whitespace so substring matching works regardless of indentation.
57		normalized := strings.Join(strings.Fields(query), " ")
58		for querySubstring, response := range d.BatchResponses {
