[metadata] {"type": "create", "filePath": "/workspace/repo/internal/storage/v2/clickhouse/metricstore/reader.go", "content": "// Copyright (c) 2025 The Jaeger Authors.
// SPDX-License-Identifier: Apache-2.0

package metricstore

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/ClickHouse/clickhouse-go/v2/lib/driver"
	"github.com/gogo/protobuf/types"

	"github.com/jaegertracing/jaeger/internal/proto-gen/api_v2/metrics"
	"github.com/jaegertracing/jaeger/internal/storage/v1/api/metricstore"
	"github.com/jaegertracing/jaeger/internal/storage/v2/clickhouse/sql"
)

var _ metricstore.Reader = (*Reader)(nil)

// errNotImplemented is returned by metric queries that are not yet supported
// by the ClickHouse metric store.
var errNotImplemented = errors.New("not implemented")

// defaultStepSeconds is the fallback step size, in seconds, used when the
// query parameters do not specify a valid step.
const defaultStepSeconds uint64 = 60

// defaultLookback is the fallback duration to look back from the end time when
// the query parameters do not specify a lookback.
const defaultLookback = time.Hour

// spanKindMapping maps OpenTelemetry span kind strings to the lowercase
// representation stored in ClickHouse.
var spanKindMapping = map[string]string{
	"SPAN_KIND_SERVER":      "server",
	"SPAN_KIND_CLIENT":      "client",
	"SPAN_KIND_UNSPECIFIED": "",
}

// Reader reads aggregated trace metrics from a ClickHouse backend.
type Reader struct {
	conn driver.Conn
}

// NewReader returns a new Reader that uses the given ClickHouse connection to
// read aggregated trace metrics.
func NewReader(conn driver.Conn) *Reader {
	return &Reader{conn: conn}
}

// GetLatencies returns latency metrics for the requested services, grouped by
// service and optionally by operation.
func (r *Reader) GetLatencies(ctx context.Context, params *metricstore.LatenciesQueryParameters) (*metrics.MetricFamily, error) {
	query := sql.SelectLatencies
	name := "service_latencies"
	if params.GroupByOperation {
		query = sql.SelectLatenciesByOperation
		name = "service_operation_latencies"
	}

	rows, err := r.conn.Query(ctx, query, latencyArgs(params)...)
	if err != nil {
		return nil, fmt.Errorf("failed to query latencies: %w", err)
	}
	defer rows.Close()

	family, err := buildMetricFamily(rows, name, params.GroupByOperation)
	if err != nil {
		return nil, err
	}
	return family, nil
}

// GetCallRates is not yet implemented for the ClickHouse metric store.
func (*Reader) GetCallRates(context.Context, *metricstore.CallRateQueryParameters) (*metrics.MetricFamily, error) {
	return nil, errNotImplemented
}

// GetErrorRates is not yet implemented for the ClickHouse metric store.
func (*Reader) GetErrorRates(context.Context, *metricstore.ErrorRateQueryParameters) (*metrics.MetricFamily, error) {
	return nil, errNotImplemented
}

// GetMinStepDuration is not yet implemented for the ClickHouse metric store.
func (*Reader) GetMinStepDuration(context.Context, *metricstore.MinStepDurationQueryParameters) (time.Duration, error) {
	return 0, errNotImplemented
}

// buildMetricFamily scans all rows and assembles them into a MetricFamily,
// grouping metric points by service (and operation when requested) while
// preserving the order in which each group was first seen.
func buildMetricFamily(rows driver.Rows, name string, groupByOperation bool) (*metrics.MetricFamily, error) {
	type metricKey struct {
		service   string
		operation string
	}

	order := make([]metricKey, 0)
	points := make(map[metricKey][]*metrics.MetricPoint)

	for rows.Next() {
		var row metricsRow
		if err := rows.ScanStruct(&row); err != nil {
			return nil, fmt.Errorf("failed to scan metrics row: %w", err)
		}

		key := metricKey{service: row.ServiceName}
		if groupByOperation {
			key.operation = row.Operation
		}
		if _, ok := points[key]; !ok {
			order = append(order, key)
		}
		points[key] = append(points[key], toMetricPoint(row))
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating metrics rows: %w", err)
	}

	family := &metrics.MetricFamily{
		Name:    name,
		Type:    metrics.MetricType_GAUGE,
		Metrics: make([]*metrics.Metric, 0, len(order)),
	}
	for _, key := range order {
		labels := []*metrics.Label{{Name: "service_name", Value: key.service}}
		if groupByOperation {
			labels = append(labels, &metrics.Label{Name: "operation", Value: key.operation})
		}
		family.Metrics = append(family.Metrics, &metrics.Metric{
			Labels:       labels,
			MetricPoints: points[key],
		})
	}
	return family, nil
}

// toMetricPoint converts a single row into a gauge metric point.
func toMetricPoint(row metricsRow) *metrics.MetricPoint {
	timestamp, _ := types.TimestampProto(row.Timestamp)
	return &metrics.MetricPoint{
		Timestamp: timestamp,
		Value: &metrics.MetricPoint_GaugeValue{
			GaugeValue: &metrics.GaugeValue{
				Value: &metrics.GaugeValue_DoubleValue{DoubleValue: row.Value},
			},
		},
	}
}

// latencyArgs builds the ordered argument list for the latency queries.
func latencyArgs(params *metricstore.LatenciesQueryParameters) []any {
	end := time.Now()
	if params.EndTime != nil {
		end = *params.EndTime
	}
	lookback := defaultLookback
	if params.Lookback != nil {
		lookback = *params.Lookback
	}
	start := end.Add(-lookback)

	spanKinds := convertSpanKinds(params.SpanKinds)
	return []any{
		stepSeconds(params.BaseQueryParameters),
		params.Quantile,
		params.ServiceNames,
		start,
		end,
		spanKinds,
		spanKinds,
	}
}

// stepSeconds converts the step duration from the query parameters into whole
// seconds. It returns defaultStepSeconds when the step is nil, zero, or
// negative, and clamps positive sub-second values to one second.
func stepSeconds(p metricstore.BaseQueryParameters) uint64 {
	if p.Step == nil || *p.Step <= 0 {
		return defaultStepSeconds
	}
	seconds := uint64(*p.Step / time.Second)
	if seconds == 0 {
		return 1
	}
	return seconds
}

// convertSpanKinds converts OpenTelemetry span kind strings into the lowercase
// representation stored in ClickHouse. Unknown kinds are omitted from the
// result while "SPAN_KIND_UNSPECIFIED" maps to an empty string.
func convertSpanKinds(kinds []string) []string {
	converted := make([]string, 0, len(kinds))
	for _, kind := range kinds {
		if mapped, ok := spanKindMapping[kind]; ok {
			converted = append(converted, mapped)
		}
	}
	return converted
}
